"""Shared pytest fixtures for the metaphysica test suite."""
from __future__ import annotations

import os
import sys
from pathlib import Path

# Make sibling-of-tests modules importable when running pytest from any cwd.
ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src"
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))


# ── where the package looks for build artifacts ─────────────────────────────
#
# The PACKAGE resolves artifacts through `generators._common.autogen_dir()`,
# which is `METAPHYSICA_OUT / AutoGenerated` and falls back to the CURRENT
# WORKING DIRECTORY. Under pytest that is the repo root, so every package-side
# reader -- the declarative gate strategies, the certificate loader, the rigor
# validator -- looked in `metaphysica/AutoGenerated` and nowhere else, while
# the published artifacts sat in the sibling `PrincipiaMetaphysica` checkout.
# That is not something the package should be taught about: a library has no
# business knowing the layout of someone's two checkouts. METAPHYSICA_OUT is
# exactly the channel for saying where the build is, so the test session says
# it, once, here.
#
# Worse than merely missing them, `autogen_dir()` MKDIRS on the way past. A
# read path with a side effect meant that any test touching it CREATED an
# empty `metaphysica/AutoGenerated`, which then satisfied every `is_dir()`
# candidate check and shadowed the real tree for the rest of the session.
#
# METAPHYSICA_OUT IS ALSO THE WRITE TARGET, so it must NEVER point at the
# published checkout. Pointing it there directly (the first attempt at this)
# let the suite write through to the real artifacts: one full run removed
# FOURTEEN rows from the published `parameters.json`, because some tests
# exercise generator write paths and those paths honour the same variable the
# read paths do. A test run that silently degrades the published build is a
# worse defect than the skips this was meant to fix.
#
# So: copy the artifacts into a per-session scratch directory and point
# METAPHYSICA_OUT at the COPY. Reads see a complete artifact set; writes land
# in scratch; the published tree is never touched. The copy is ~32 MB and
# happens once per session.
#
# Set only when the caller has not already chosen, so an explicit
# METAPHYSICA_OUT still wins and per-test monkeypatching is unaffected.
def _stage_artifacts_for_reading() -> None:
    import shutil
    import tempfile

    if os.environ.get("METAPHYSICA_OUT"):
        return
    for root in (ROOT, ROOT.parent / "PrincipiaMetaphysica",
                 Path("H:/Github/PrincipiaMetaphysica")):
        source = root / "AutoGenerated"
        if not (source / "parameters.json").is_file():
            continue
        if root == ROOT:
            # The repo-local tree is already scratch; nothing to protect.
            os.environ["METAPHYSICA_OUT"] = str(root)
            return
        staged = Path(tempfile.mkdtemp(prefix="metaphysica-artifacts-"))
        shutil.copytree(source, staged / "AutoGenerated")
        os.environ["METAPHYSICA_OUT"] = str(staged)
        return


_stage_artifacts_for_reading()
